<script setup>
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AdminSidebar from './AdminSidebar.vue';
import RedesignTopbar from './RedesignTopbar.vue';
import { computed, onBeforeUnmount, ref } from 'vue';
const props = defineProps({ user: Object, status: String });
const photoInput = ref(null);
const photoObjectUrl = ref('');
const avatarUrl = computed(() => photoObjectUrl.value || (props.user?.profile_photo ? `/storage/${props.user.profile_photo}` : ''));
const initials = computed(() => (props.user?.name || 'U').trim().split(/\s+/).slice(0, 2).map(part => part[0]).join('').toUpperCase());
const profile = useForm({ _method: 'PATCH', name: props.user?.name || '', username: props.user?.username || '', email: props.user?.email || '', location: props.user?.location || '', experience: props.user?.experience || '', skills_text: Array.isArray(props.user?.skills) ? props.user.skills.join(', ') : '', bio: props.user?.bio || '', profile_photo: null });
const password = useForm({ current_password: '', password: '', password_confirmation: '' });
const selectPhoto = () => photoInput.value?.click();
const handlePhoto = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (photoObjectUrl.value) URL.revokeObjectURL(photoObjectUrl.value);
    photoObjectUrl.value = URL.createObjectURL(file);
    profile.profile_photo = file;
};
const save = () => profile.post(route('admin.profile.update'), { preserveScroll: true, onSuccess: () => {
    profile.profile_photo = null;
    router.visit(route('redesign.profile'), { preserveScroll: true });
} });
const savePassword = () => password.put(route('password.update'), { preserveScroll: true, errorBag: 'updatePassword', onSuccess: () => password.reset() });
onBeforeUnmount(() => { if (photoObjectUrl.value) URL.revokeObjectURL(photoObjectUrl.value); });
</script>
<template>
    <Head title="Profil & keamanan" />
    <div class="profile-app"><AdminSidebar /><main><RedesignTopbar breadcrumb="Profil" /><div class="content"><div class="heading"><div><h1>Profil & keamanan</h1><p>Kelola informasi akun dan keamanan dalam satu workspace.</p></div></div><div class="columns"><section class="panel"><h2>Informasi profil & keamanan</h2><p>Lengkapi detail berikut.</p><div class="photo-field"><div class="avatar" aria-label="Preview foto profil"><img v-if="avatarUrl" :src="avatarUrl" alt="Preview foto profil" /><span v-else>{{ initials }}</span></div><div class="photo-actions"><strong>Foto profil</strong><p>JPG atau PNG, maksimal 2 MB. Foto baru tampil di preview sebelum disimpan.</p><input ref="photoInput" type="file" accept="image/jpeg,image/png" class="visually-hidden" @change="handlePhoto" /><button type="button" class="photo-button" @click="selectPhoto">{{ avatarUrl ? 'Ganti foto' : 'Pilih foto' }}</button><small v-if="profile.errors.profile_photo" role="alert">{{ profile.errors.profile_photo }}</small></div></div><form id="profile-form" @submit.prevent="save" class="fields"><label>Nama lengkap<input v-model="profile.name" required autocomplete="name" /><small v-if="profile.errors.name">{{ profile.errors.name }}</small></label><label>Username<input v-model="profile.username" required autocomplete="username" /><small v-if="profile.errors.username">{{ profile.errors.username }}</small></label><label>Email<input v-model="profile.email" type="email" required autocomplete="email" /><small v-if="profile.errors.email">{{ profile.errors.email }}</small></label><label>Lokasi<input v-model="profile.location" autocomplete="address-level2" /><small v-if="profile.errors.location">{{ profile.errors.location }}</small></label><label>Pengalaman / tagline<input v-model="profile.experience" /><small v-if="profile.errors.experience">{{ profile.errors.experience }}</small></label><label>Keahlian<input v-model="profile.skills_text" placeholder="Pisahkan dengan koma" /><small v-if="profile.errors.skills_text">{{ profile.errors.skills_text }}</small></label><label class="bio">Bio<textarea v-model="profile.bio" rows="3" /><small v-if="profile.errors.bio">{{ profile.errors.bio }}</small></label></form><div class="profile-actions"><button form="profile-form" type="submit" class="primary" :disabled="profile.processing">{{ profile.processing ? 'Menyimpan...' : 'Simpan profil' }}</button><Link :href="route('redesign.admin-dashboard')" class="cancel">Batal</Link></div><form id="password-form" @submit.prevent="savePassword" class="fields password-fields"><label>Kata sandi saat ini<input v-model="password.current_password" type="password" autocomplete="current-password" /><small v-if="password.errors.current_password">{{ password.errors.current_password }}</small></label><div></div><label>Kata sandi baru<input v-model="password.password" type="password" autocomplete="new-password" /><small v-if="password.errors.password">{{ password.errors.password }}</small></label><label>Konfirmasi kata sandi<input v-model="password.password_confirmation" type="password" autocomplete="new-password" /><small v-if="password.errors.password_confirmation">{{ password.errors.password_confirmation }}</small></label></form><div class="actions"><button form="password-form" class="primary" :disabled="password.processing || !password.password">Perbarui kata sandi</button></div><p v-if="props.status === 'profile-updated'" role="status" class="success">Profil berhasil diperbarui.</p></section><aside><section class="panel guide"><h2>Panduan pengisian</h2><p>Informasi akun dan keamanan dipisahkan. Role ditampilkan sebagai informasi akses, bukan field yang dapat diedit.</p></section><section class="panel guide"><h2>Konteks akses</h2><p>{{ props.user?.role?.replaceAll('_', ' ') }}<br />Hak akses mengikuti role di aplikasi.</p></section></aside></div></div></main></div>
</template>
<style scoped>
