ffset:2px}@media(max-width:900px){.columns{grid-template-columns:1fr}.guide{min-height:0}}@media(max-width:800px){.profile-app{display:block}}@media(max-width:600px){.content{padding:22px 14px}.heading{align-items:flex-start;flex-direction:column}.fields{grid-template-columns:1fr;gap:18px}.bio{grid-column:auto}.password-fields>div{display:none}.actions{flex-wrap:wrap}.panel{padding:18px}}
</style>
<style scoped>
.profile-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:28px}.profile-actions .primary{min-width:180px}.password-fields{margin-top:32px}.actions{margin-top:18px}
.photo-field{display:flex;align-items:center;gap:20px;margin-top:26px;padding:18px;border:1px solid #dce6e8;border-radius:10px;background:#fafbfc}.avatar{width:88px;height:88px;flex:none;border-radius:50%;overflow:hidden;background:#dff2ee;color:#007f78;display:grid;place-items:center;font-size:24px;font-weight:750}.avatar img{width:100%;height:100%;object-fit:cover}.photo-actions strong{display:block;font-size:13px}.photo-actions p{font-size:12px;color:#70858c;margin:6px 0 12px}.photo-actions small{display:block;margin-top:8px;color:#b74336}.photo-button{border:1px solid #dce6e8;border-radius:8px;padding:10px 16px;color:#007f78;font-weight:700;background:#fff;cursor:pointer}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:600px){.photo-field{align-items:flex-start;flex-wrap:wrap}}
